// src/smoke/BombSmokeScreen.jsx — SMOKE ONLY, NEVER MERGE.
//
// Research Modal Build A, spec §8: the six Bomb mode states on a phone, from
// committed JSON fixtures shaped from real battle documents (the measured ones
// generated by the real corrected-battle harness, scorer and committed patch;
// no production read). `?bombFixture=held|approaching|banked|closed|preview|held_legacy|held_crypto|legacy_no_entry`.
//
// Ruling 2026-11-07 (§0.4(a), rule (i)): a held legacy-scored position — a
// legacy stock (held_legacy, legacy_no_entry) or a crypto on any battle
// (held_crypto: a starting crypto on the stamped battle) — draws the preview
// with the held line, nothing banked and no clock.
//
// The page fixes the clock to the fixture's instant (so a Saturday visit still
// shows a market-hours state), answers /api/stocks/historical from generated
// bars, and mounts the real AssetResearchModal exactly as the Battle View does,
// with the bombContext the real selector builds.

import React, { useEffect, useState } from 'react';
import AssetResearchModal from '../components/draft/AssetResearchModal';
import { selectBombRecord } from '../components/Research/BombMode/selectBombRecord';
import { enrichHeldPosition } from '../screens/AgentBattleScreen';
import { buildResearchAsset } from '../utils/researchAssetBuilder';
import BATTLES from './bombFixtures.battles.json';

export const BOMB_FIXTURE_STATES = ['held', 'approaching', 'banked', 'closed', 'preview', 'held_legacy', 'held_crypto', 'legacy_no_entry'];

const STATES = {
  held: { now: '2026-10-16T18:47:00.000Z', battle: 'heldBanked', symbol: 'EOG', live: 161.48 },
  approaching: { now: '2026-10-16T17:11:12.000Z', battle: 'before', symbol: 'EOG', live: 160.27, minuteTo: '2026-10-16T17:07:00.000Z' },
  banked: { now: '2026-10-16T17:15:19.000Z', battle: 'before', symbol: 'EOG', live: 160.3, minuteTo: '2026-10-16T17:12:00.000Z', then: { afterMs: 5000, battle: 'after', live: 160.41 } },
  closed: { now: '2026-10-16T20:30:00.000Z', battle: 'heldBanked', symbol: 'EOG', live: 162.86, minuteTo: '2026-10-16T19:59:00.000Z' },
  preview: { now: '2026-10-16T18:47:00.000Z', battle: 'heldBanked', symbol: 'XOM', live: 112.4, preview: true },
  held_legacy: { now: '2026-10-16T17:11:00.000Z', battle: 'legacyHeld', symbol: 'EOG', live: 160.27 },
  held_crypto: { now: '2026-10-16T17:11:00.000Z', battle: 'heldCrypto', symbol: 'BTC', live: 66480 },
  legacy_no_entry: { now: '2026-10-16T17:11:00.000Z', battle: 'legacyNoEntry', symbol: 'EOG', live: 160.27 },
};

/** Install the fixture clock: Date.now() and new Date() read the fixture's instant, then advance in real time. */
function installClock(nowIso) {
  if (globalThis.__bombSmokeClock) return;
  const Real = Date;
  const offset = Real.parse(nowIso) - Real.now();
  class FixtureDate extends Real {
    constructor(...a) { super(...(a.length ? a : [Real.now() + offset])); }
    static now() { return Real.now() + offset; }
  }
  globalThis.Date = FixtureDate;
  globalThis.__bombSmokeClock = true;
}

// ── Bars: a deterministic EOG climb over two weeks, ET = UTC−4 in October ───
const SESSIONS = ['2026-10-05', '2026-10-06', '2026-10-07', '2026-10-08', '2026-10-09', '2026-10-12', '2026-10-13', '2026-10-14', '2026-10-15', '2026-10-16'];
function rand(seed) { let s = seed; return () => { s = (s * 9301 + 49297) % 233280; return s / 233280; }; }
function thirtyMinute(symbol, untilMs) {
  const r = rand(symbol === 'EOG' ? 11 : symbol === 'BTC' ? 3 : 7);
  const startPx = symbol === 'EOG' ? 146 : symbol === 'BTC' ? 62100 : 109;
  const endPx = symbol === 'EOG' ? 161.4 : symbol === 'BTC' ? 66400 : 112.4;
  const wiggle = symbol === 'BTC' ? 260 : 0.9;
  const bars = [];
  const total = SESSIONS.length * 13;
  SESSIONS.forEach((d, di) => {
    for (let i = 0; i < 13; i += 1) {
      const t = Date.parse(`${d}T13:30:00.000Z`) + i * 30 * 60 * 1000;
      if (t + 30 * 60 * 1000 > untilMs) continue; // closed bars only
      const k = di * 13 + i;
      const base = startPx + (endPx - startPx) * (k / total) + (r() - 0.5) * wiggle;
      const u = wiggle / 0.9;
      bars.push({ t, o: base - 0.15 * u, h: base + 0.35 * u, l: base - 0.4 * u, c: base });
    }
  });
  return bars;
}
function oneMinute(live, toMs) {
  const r = rand(5);
  const bars = [];
  for (let i = 59; i >= 0; i -= 1) {
    const t = toMs - i * 60 * 1000;
    const c = live - 0.9 * (i / 59) + (r() - 0.5) * 0.18;
    bars.push({ t, o: c - 0.03, h: c + 0.06, l: c - 0.07, c });
  }
  return bars;
}
const asApi = (bars) => bars.slice().reverse().map((b) => ({ date: new Date(b.t).toISOString(), datetime: new Date(b.t).toISOString(), timestamp: Math.floor(b.t / 1000), open: +b.o.toFixed(2), high: +b.h.toFixed(2), low: +b.l.toFixed(2), close: +b.c.toFixed(2), volume: 1000 }));

function installFetch(spec) {
  if (globalThis.__bombSmokeFetch) return;
  const real = globalThis.fetch.bind(globalThis);
  globalThis.fetch = async (input, init) => {
    const url = new URL(typeof input === 'string' ? input : input.url, window.location.origin);
    if (url.pathname === '/api/stocks/historical') {
      const symbol = url.searchParams.get('symbol');
      const tf = url.searchParams.get('timeframe');
      const nowMs = Date.now();
      let data = [];
      if (tf === '30m') data = asApi(thirtyMinute(symbol, nowMs));
      else if (tf === '1m') data = asApi(oneMinute(spec.live, Date.parse(spec.minuteTo || spec.now)));
      else if (tf === '1d' && !spec.noDaily) {
        data = symbol === 'BTC'
          ? [{ date: '2026-10-16', open: 65200, high: 66620, low: 64900, close: spec.live, volume: 1 }, { date: '2026-10-15', open: 64300, high: 65400, low: 64000, close: 65100, volume: 1 }]
          : [{ date: '2026-10-16', open: 160.5, high: 162, low: 159.9, close: spec.live, volume: 1 }, { date: '2026-10-15', open: 159, high: 161, low: 158.8, close: symbol === 'XOM' ? 111.5 : 160.6, volume: 1 }];
      }
      return new Response(JSON.stringify({ success: true, data, timeframe: tf }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    if (url.pathname.startsWith('/api/')) return new Response(JSON.stringify({ success: false }), { status: 404, headers: { 'Content-Type': 'application/json' } });
    return real(input, init);
  };
  globalThis.__bombSmokeFetch = true;
}

function clearFixtureCache() {
  try {
    for (let i = localStorage.length - 1; i >= 0; i -= 1) {
      const k = localStorage.key(i);
      if (k && (k.includes('ohlcv_EOG') || k.includes('ohlcv_XOM') || k.includes('ohlcv_BTC'))) localStorage.removeItem(k);
    }
  } catch { /* storage unavailable */ }
}

export default function BombSmokeScreen({ state }) {
  const spec = STATES[state] || STATES.held;
  installClock(spec.now);
  installFetch(spec);
  clearFixtureCache();
  const [phase, setPhase] = useState(0);
  useEffect(() => {
    if (!spec.then) return undefined;
    const id = setTimeout(() => setPhase(1), spec.then.afterMs);
    return () => clearTimeout(id);
  }, [spec]);
  const battle = BATTLES[phase === 1 ? spec.then.battle : spec.battle];
  const live = phase === 1 ? spec.then.live : spec.live;
  let asset;
  let bombContext;
  if (spec.preview) {
    asset = buildResearchAsset({ symbol: 'XOM', name: 'Exxon Mobil' }, { livePrices: { XOM: live }, thresholds: { XOM: { threshold: 2.5 } }, startingPrices: {}, useDefaultThreshold: true });
    bombContext = { kind: 'agent', battleId: battle.id, held: false, record: null };
  } else {
    // The agent's position holding the fixture's symbol (star → core → support), as the Battle View finds it.
    const sym = spec.symbol;
    const [tier, slot] = ['star', 'core', 'support'].flatMap((t) => (battle.portfolio[t] || []).map((p, i) => (p.symbol === sym ? [t, i] : null))).find(Boolean);
    const pos = battle.portfolio[tier][slot];
    const row = pos.stockThresholdReceipt ? enrichHeldPosition(pos, tier, { stockBattle: battle, stockSide: 'agent', stockSlot: slot }) : { ...pos, tier };
    asset = buildResearchAsset(row, { livePrices: { [sym]: live }, thresholds: { [sym]: { threshold: sym === 'BTC' ? 4 : 3.6 } }, startingPrices: battle.portfolio.startingPrices || {}, useDefaultThreshold: true });
    const record = selectBombRecord(battle, sym, Date.now());
    bombContext = { kind: 'agent', battleId: battle.id, held: record !== null, record };
  }
  return (
    <div style={{ minHeight: '100vh', background: 'var(--ft-bg-dashboard)' }}>
      <div style={{ position: 'fixed', top: 6, left: 8, zIndex: 100000, fontSize: 10, color: 'var(--ft-ink-3)', fontFamily: 'monospace' }}>SMOKE · {state}</div>
      <AssetResearchModal asset={asset} onClose={() => {}} showActionButton={false} isGameContext version={2} defaultTab="baggerbomb" defaultTimeframe="bomb" wsPrice={live} bombContext={bombContext} />
    </div>
  );
}
